/* ════════════════════════════════════════════════════════════════════
   GioTV SHOWS DATA — single source of truth for shows.html + episodes.html
   ────────────────────────────────────────────────────────────────────
   To ADD A SHOW:      copy a block below, give it a new slug (the key).
   To ADD AN EPISODE:  append an object to that show's episodes[] array.
   Fields per episode:
     season   → season number (shown as "Season 1 · Episode …" above the name)
     code     → episode number within the season (e.g. "1B")
     title    → episode name (no "Episode …:" prefix — the number line carries it)
     videoId  → the YouTube id (youtu.be/XXXX… the part after /watch?v=)
     watch    → the full YouTube link you want to share
     Optional per episode:
     thumb    → thumbnail override: a local file (e.g. "images/ep.jpg")
                 or an inline data URI. If empty, the episode's YouTube
                 hq thumbnail is fetched automatically (works online, but
                 NOT in offline/sandboxed previews).
   Optional per show:
     poster   → image for the show box. Either one source (e.g.
                 "spongy-poster.jpg") or a fallback chain as an array
                 — each entry is tried in order, so an inline data URI
                 after the file guarantees the poster renders even in
                 network-less previews. If empty, the show box falls
                 back to the first episode's thumbnail.
   ════════════════════════════════════════════════════════════════════ */
window.GIOTV_SHOWS = {

  "the-spongy-technician": {
    title: "The Spongy Technician",
    badge: "ST",
    tagline: "Tech Modding",
    poster: [
      "spongy-technician.jpg",
      "data:image/jpeg;base64,"
    ],
    episodes: [
      {
        season: 1,
        code: "1A",
        title: "Installing android 13 on an HTC One M8",
        videoId: "gIUMwa0qFMM",
        watch: "https://youtu.be/gIUMwa0qFMM?si=-_fm3DflgPJOwQNX",
        thumb: "data:image/jpeg;base64,"
      }
    ]
  }

};
